const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const samples = await IO.loadMNIST(100);
if (samples.length < 2) throw new Error("At least two MNIST images are required");

const network = NeuralNet.builder()
    .input(2)
    .positionalEncoding(2)
    .layer(8)
    .layer(8)
    .layer(1, NeuralNet.ACTIVATIONS.sigmoid)
    .build();
const coordinates = Array.from({length: 28 * 28}, (_, i) =>
    [(i % 28) / 27, 1 - Math.floor(i / 28) / 27]);
const weightKeys = Object.keys(network.weightsMap).sort();
const initialWeights = OPTIMIZERS.ADAMW().initTheta(weightKeys);

// Shared initialization aligns parameter names, but does not make weights translation-invariant.
const fitImage = async pixels => {
    const optimizer = OPTIMIZERS.ADAMW({learningRate: 0.01});
    optimizer.initTheta = () => ({...initialWeights});
    const {theta} = await fitDataAsync(coordinates, pixels, network.model, {
        epochs: 300,
        batch: 32,
        optimizer,
        continuationEvery: 50,
        continuationFn: () => {},
    });
    return theta;
};
const weightVector = theta => vec(...weightKeys.map(key => theta[key]));

const status = document.createElement("div");
status.style.maxWidth = "280px";
status.style.whiteSpace = "normal";
status.textContent = "Training image networks...";
const reconstruction = IO.paintMNIST(new Float32Array(28 * 28));
const image = IO.paintMNIST(new Float32Array(28 * 28));
let model;
let sampleForTarget;
let initializationFailed = false;
let busy = false;

const initialize = async () => {
    const targets = [];
    for (let i = 0; i < samples.length; i++) {
        status.textContent = `Training image networks: ${i + 1}/${samples.length}`;
        targets.push(weightVector(await fitImage(samples[i])));
    }
    sampleForTarget = new Map(targets.map((target, index) => [target, samples[index]]));
    status.textContent = "Building nearest-neighbor index...";
    await new Promise(resolve => setTimeout(resolve, 0));
    model = HKmeans.new(targets, {rho: 0.1, kmeansIter: 2}).fit();
    status.textContent = "Ready. Draw or randomize an image, then submit.";
};

const drawing = IO.drawMNIST({
    randomButton: true,
    onSubmit: data => {
        if (!model) {
            if (!initializationFailed) status.textContent = "Still training; submit again when ready.";
            return;
        }
        if (busy) {
            status.textContent = "A submitted image is already training.";
            return;
        }
        const pixels = Float32Array.from(data);
        busy = true;
        status.textContent = "Training submitted image...";
        fitImage(pixels).then(theta => {
            network.setWeights(theta);
            reconstruction.update(Float32Array.from(coordinates.map(point => network.eval(point))));
            image.update(sampleForTarget.get(model.findNN(weightVector(theta))));
            status.textContent = "Showing the submitted image reconstruction and its nearest MNIST sample.";
        }).catch(error => {
            console.error("Could not train submitted image:", error);
            status.textContent = `Could not train submitted image: ${error.message}`;
        }).finally(() => {
            busy = false;
        });
    },
});
const displayImage = visual => {
    const canvas = visual.toVisual().value()[0];
    canvas.DOM.style.display = "block";
    return canvas;
};
const ui = IO.UI(
    {type: "canvas", value: () => status},
    {type: "canvas", value: () => drawing},
    {type: "canvas", value: () => displayImage(reconstruction)},
    {type: "canvas", value: () => displayImage(image)},
);

setTimeout(() => {
    initialize().catch(error => {
        initializationFailed = true;
        console.error("Could not initialize nearest-neighbor demo:", error);
        status.textContent = `Could not initialize nearest-neighbor demo: ${error.message}`;
    });
}, 0);
ui;
